 $('#place').textContent=e.place;$('#scene-condition').textContent=s.finished?'CHAPTER COMPLETE':s.paused?(teen()?'PHONE PAUSED':'MISSION PAUSED'):s.ended?(teen()?'PASS ENDED':'MISSION REVOKED'):s.delivered?'DELIVERED':s.message&&!s.verified?'NEW MESSAGE':'';
